//! Hook installers. Today only Claude Code is supported. Cursor,
//! Gemini CLI, Windsurf and Cline follow the same pattern but their
//! settings schemas differ slightly — implementing them is
//! straightforward but out of scope for the first landing of this
//! module.
//!
//! The Claude Code installer:
//!
//! 1. Reads or creates `settings.json` (global: `~/.claude/settings.json`,
//!    local: `./.claude/settings.json`).
//! 2. Adds a `hooks.PreToolUse` entry that fires `sophon hook rewrite
//!    --agent claude` for every `Bash(*)` tool call. Claude Code then
//!    uses the rewriter's stdout to decide whether to run the command
//!    unchanged or a rewritten version.
//! 3. Optionally writes a `SOPHON.md` next to the settings with a short
//!    description of what the hook does and how to opt out.
//!
//! Everything is idempotent: running the installer twice leaves the
//! settings file in the same state.

use std::fs;
use std::io;
use std::path::{Path, PathBuf};

use serde_json::{json, Value};

#[derive(Debug, thiserror::Error)]
pub enum InstallError {
    #[error("could not locate home directory")]
    HomeNotFound,
    #[error("io error: {0}")]
    Io(#[from] io::Error),
    #[error("serde_json error: {0}")]
    Json(#[from] serde_json::Error),
    #[error("malformed settings.json: {0}")]
    InvalidSettings(String),
    #[error("unknown agent: {0}")]
    UnknownAgent(String),
    #[error("agent {0} not yet supported by the installer — only claude today")]
    AgentNotSupported(&'static str),
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SupportedAgent {
    Claude,
    Cursor,
    Gemini,
    Windsurf,
    Cline,
}

impl SupportedAgent {
    pub fn parse(name: &str) -> Option<Self> {
        match name.to_ascii_lowercase().as_str() {
            "claude" | "claude-code" | "claudecode" => Some(Self::Claude),
            "cursor" => Some(Self::Cursor),
            "gemini" | "gemini-cli" => Some(Self::Gemini),
            "windsurf" => Some(Self::Windsurf),
            "cline" => Some(Self::Cline),
            _ => None,
        }
    }

    pub fn as_str(&self) -> &'static str {
        match self {
            Self::Claude => "claude",
            Self::Cursor => "cursor",
            Self::Gemini => "gemini",
            Self::Windsurf => "windsurf",
            Self::Cline => "cline",
        }
    }
}

/// Hook installer facade.
pub struct HookInstaller;

impl HookInstaller {
    /// Install Sophon hooks for `agent`. Only `Claude` is wired today.
    /// Resolves the settings path from `agent` and `global`, then
    /// delegates to [`Self::install_at`].
    pub fn install(agent: SupportedAgent, global: bool) -> Result<InstallReport, InstallError> {
        let path = Self::settings_path_for(agent, global)?;
        Self::install_at(agent, path)
    }

    /// Remove Sophon hooks for `agent`.
    pub fn uninstall(agent: SupportedAgent, global: bool) -> Result<InstallReport, InstallError> {
        let path = Self::settings_path_for(agent, global)?;
        Self::uninstall_at(agent, path)
    }

    /// Install at an explicit settings path. Exposed for tests and for
    /// tools that want to point at a custom location.
    pub fn install_at(
        agent: SupportedAgent,
        settings_path: PathBuf,
    ) -> Result<InstallReport, InstallError> {
        match agent {
            SupportedAgent::Claude => Self::install_claude_at(settings_path),
            other => Err(InstallError::AgentNotSupported(other.as_str())),
        }
    }

    /// Uninstall at an explicit settings path.
    pub fn uninstall_at(
        agent: SupportedAgent,
        settings_path: PathBuf,
    ) -> Result<InstallReport, InstallError> {
        match agent {
            SupportedAgent::Claude => Self::uninstall_claude_at(settings_path),
            other => Err(InstallError::AgentNotSupported(other.as_str())),
        }
    }

    fn settings_path_for(agent: SupportedAgent, global: bool) -> Result<PathBuf, InstallError> {
        match agent {
            SupportedAgent::Claude => Self::claude_settings_path(global),
            other => Err(InstallError::AgentNotSupported(other.as_str())),
        }
    }

    fn install_claude_at(settings_path: PathBuf) -> Result<InstallReport, InstallError> {
        let mut settings = Self::read_settings(&settings_path)?;

        // hooks.PreToolUse = [ { matcher: "Bash(*)", hook: {...} } ]
        let hooks_obj = settings
            .as_object_mut()
            .ok_or_else(|| InstallError::InvalidSettings("top-level is not an object".into()))?
            .entry("hooks")
            .or_insert_with(|| json!({}));

        let hooks_obj = hooks_obj
            .as_object_mut()
            .ok_or_else(|| InstallError::InvalidSettings("hooks is not an object".into()))?;

        let pre = hooks_obj.entry("PreToolUse").or_insert_with(|| json!([]));

        let pre_arr = pre.as_array_mut().ok_or_else(|| {
            InstallError::InvalidSettings("hooks.PreToolUse is not an array".into())
        })?;

        // Remove any existing Sophon entry so repeated installs are
        // idempotent.
        pre_arr.retain(|entry| {
            entry
                .get("hook")
                .and_then(|h| h.get("command"))
                .and_then(|c| c.as_str())
                .map(|s| !s.contains("sophon hook rewrite"))
                .unwrap_or(true)
        });

        pre_arr.push(json!({
            "matcher": "Bash(*)",
            "hook": {
                "type": "command",
                "command": "sophon hook rewrite --agent claude"
            }
        }));

        Self::write_settings(&settings_path, &settings)?;
        let md_path = Self::write_sophon_md(&settings_path)?;

        Ok(InstallReport {
            agent: SupportedAgent::Claude,
            settings_path: settings_path.clone(),
            notes_path: Some(md_path),
            action: InstallAction::Installed,
        })
    }

    fn uninstall_claude_at(settings_path: PathBuf) -> Result<InstallReport, InstallError> {
        if !settings_path.exists() {
            return Ok(InstallReport {
                agent: SupportedAgent::Claude,
                settings_path,
                notes_path: None,
                action: InstallAction::NotInstalled,
            });
        }

        let mut settings = Self::read_settings(&settings_path)?;

        let removed = if let Some(hooks) = settings.get_mut("hooks").and_then(|h| h.as_object_mut())
        {
            if let Some(pre) = hooks.get_mut("PreToolUse").and_then(|p| p.as_array_mut()) {
                let before = pre.len();
                pre.retain(|entry| {
                    entry
                        .get("hook")
                        .and_then(|h| h.get("command"))
                        .and_then(|c| c.as_str())
                        .map(|s| !s.contains("sophon hook rewrite"))
                        .unwrap_or(true)
                });
                before - pre.len()
            } else {
                0
            }
        } else {
            0
        };

        Self::write_settings(&settings_path, &settings)?;

        Ok(InstallReport {
            agent: SupportedAgent::Claude,
            settings_path,
            notes_path: None,
            action: if removed > 0 {
                InstallAction::Uninstalled
            } else {
                InstallAction::NotInstalled
            },
        })
    }

    fn claude_settings_path(global: bool) -> Result<PathBuf, InstallError> {
        if global {
            let home = home_dir().ok_or(InstallError::HomeNotFound)?;
            Ok(home.join(".claude").join("settings.json"))
        } else {
            Ok(PathBuf::from(".claude/settings.json"))
        }
    }

    fn read_settings(path: &Path) -> Result<Value, InstallError> {
        if !path.exists() {
            return Ok(json!({}));
        }
        let raw = fs::read_to_string(path)?;
        if raw.trim().is_empty() {
            return Ok(json!({}));
        }
        let parsed: Value = serde_json::from_str(&raw)?;
        Ok(parsed)
    }

    fn write_settings(path: &Path, settings: &Value) -> Result<(), InstallError> {
        if let Some(parent) = path.parent() {
            fs::create_dir_all(parent)?;
        }
        let pretty = serde_json::to_string_pretty(settings)?;
        fs::write(path, pretty)?;
        Ok(())
    }

    fn write_sophon_md(settings_path: &Path) -> Result<PathBuf, InstallError> {
        let md_path = settings_path
            .parent()
            .map(|p| p.join("SOPHON.md"))
            .unwrap_or_else(|| PathBuf::from("SOPHON.md"));

        let content = SOPHON_MD_TEMPLATE;
        fs::write(&md_path, content)?;
        Ok(md_path)
    }
}

/// Return value of the installer — tells the CLI what happened and
/// which file was touched.
#[derive(Debug, Clone)]
pub struct InstallReport {
    pub agent: SupportedAgent,
    pub settings_path: PathBuf,
    pub notes_path: Option<PathBuf>,
    pub action: InstallAction,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum InstallAction {
    Installed,
    Uninstalled,
    NotInstalled,
}

fn home_dir() -> Option<PathBuf> {
    // Avoid pulling in the `dirs` crate for one function.
    std::env::var_os("HOME").map(PathBuf::from)
}

const SOPHON_MD_TEMPLATE: &str = r#"# Sophon Hooks

Sophon auto-wraps most shell commands with `sophon exec -- …` so that
their output is compressed before it reaches the LLM context.

## What it does

- `git status` → `sophon exec -- git status` (dropped to ~30 %)
- `cargo test` → `sophon exec -- cargo test` (failures only)
- `ls -la`, `tree` → grouped by extension
- `docker ps` → only NAMES / STATUS / PORTS columns
- `grep / rg` → grouped by file
- Many more — see `sophon hook status`.

## How to opt out

Run `sophon hook uninstall --agent claude` to remove the hook, or
list exclusion prefixes in `~/.sophon/hooks.toml`:

```toml
[hooks]
exclude = ["git log --graph"]  # any command starting with these is left alone
```

Pipelines (`cmd | cmd`), heredocs, and any command already prefixed with
`sophon ` are always passed through unchanged.

## Stats

```
sophon stats
```
"#;

#[cfg(test)]
mod tests {
    use super::*;
    use tempfile::tempdir;

    #[test]
    fn parse_supported_agent() {
        assert_eq!(
            SupportedAgent::parse("claude"),
            Some(SupportedAgent::Claude)
        );
        assert_eq!(
            SupportedAgent::parse("Claude-Code"),
            Some(SupportedAgent::Claude)
        );
        assert_eq!(
            SupportedAgent::parse("cursor"),
            Some(SupportedAgent::Cursor)
        );
        assert_eq!(SupportedAgent::parse("nope"), None);
    }

    fn tmp_settings(dir: &tempfile::TempDir) -> PathBuf {
        dir.path().join("claude").join("settings.json")
    }

    #[test]
    fn install_at_creates_settings() {
        let dir = tempdir().unwrap();
        let path = tmp_settings(&dir);

        let report = HookInstaller::install_at(SupportedAgent::Claude, path.clone()).unwrap();
        assert_eq!(report.action, InstallAction::Installed);
        assert_eq!(report.settings_path, path);

        let raw = fs::read_to_string(&path).unwrap();
        assert!(raw.contains("sophon hook rewrite"));
        assert!(raw.contains("PreToolUse"));
        assert!(raw.contains("Bash(*)"));
    }

    #[test]
    fn install_at_is_idempotent() {
        let dir = tempdir().unwrap();
        let path = tmp_settings(&dir);

        HookInstaller::install_at(SupportedAgent::Claude, path.clone()).unwrap();
        HookInstaller::install_at(SupportedAgent::Claude, path.clone()).unwrap();

        let raw = fs::read_to_string(&path).unwrap();
        let parsed: Value = serde_json::from_str(&raw).unwrap();
        let pre = parsed
            .get("hooks")
            .and_then(|h| h.get("PreToolUse"))
            .and_then(|p| p.as_array())
            .unwrap();
        let sophon_entries = pre
            .iter()
            .filter(|e| {
                e.get("hook")
                    .and_then(|h| h.get("command"))
                    .and_then(|c| c.as_str())
                    .map(|s| s.contains("sophon hook rewrite"))
                    .unwrap_or(false)
            })
            .count();
        assert_eq!(sophon_entries, 1, "duplicate Sophon hook after 2 installs");
    }

    #[test]
    fn uninstall_at_removes_hook_entry() {
        let dir = tempdir().unwrap();
        let path = tmp_settings(&dir);

        HookInstaller::install_at(SupportedAgent::Claude, path.clone()).unwrap();
        let report = HookInstaller::uninstall_at(SupportedAgent::Claude, path.clone()).unwrap();
        assert_eq!(report.action, InstallAction::Uninstalled);
        let raw = fs::read_to_string(&path).unwrap();
        assert!(!raw.contains("sophon hook rewrite"));
    }

    #[test]
    fn uninstall_at_reports_not_installed_when_missing() {
        let dir = tempdir().unwrap();
        let path = tmp_settings(&dir);
        let report = HookInstaller::uninstall_at(SupportedAgent::Claude, path).unwrap();
        assert_eq!(report.action, InstallAction::NotInstalled);
    }

    #[test]
    fn cursor_agent_not_supported_yet() {
        let dir = tempdir().unwrap();
        let path = tmp_settings(&dir);
        let err = HookInstaller::install_at(SupportedAgent::Cursor, path).unwrap_err();
        assert!(matches!(err, InstallError::AgentNotSupported(_)));
    }

    #[test]
    fn install_preserves_existing_settings_keys() {
        let dir = tempdir().unwrap();
        let path = tmp_settings(&dir);
        fs::create_dir_all(path.parent().unwrap()).unwrap();
        fs::write(&path, r#"{"permissions":{"allow":["Bash(cargo test)"]}}"#).unwrap();

        HookInstaller::install_at(SupportedAgent::Claude, path.clone()).unwrap();

        let raw = fs::read_to_string(&path).unwrap();
        let parsed: Value = serde_json::from_str(&raw).unwrap();
        assert!(
            parsed.get("permissions").is_some(),
            "pre-existing keys lost"
        );
        assert!(parsed.get("hooks").is_some(), "hooks key missing");
    }
}

//! Command rewriter.
//!
//! The rewriter turns a raw shell command into one of two outcomes:
//!
//! - `Passthrough(cmd)` — the caller should run `cmd` verbatim. Used for
//!   commands that already start with `sophon `, that the user has
//!   excluded, or that don't match any rule.
//!
//! - `Rewritten { original, rewritten }` — the caller should run
//!   `rewritten` instead. `rewritten` is always of the form
//!   `sophon exec -- <original>` so the downstream `sophon exec`
//!   executes the real command and pipes its output through the
//!   `output-compressor` filters before returning to the LLM.
//!
//! The rule set is a flat `Vec<RewriteRule>` matched top-to-bottom.
//! All rules are deterministic regexes — no ML, no heuristics.

use once_cell::sync::Lazy;
use regex::Regex;

/// A single rewrite rule.
#[derive(Debug, Clone)]
pub struct RewriteRule {
    /// Human-readable name (appears in rewriter diagnostics).
    pub name: &'static str,
    /// Regex matched against the full command string.
    pub pattern: Regex,
}

impl RewriteRule {
    fn new(name: &'static str, pattern: &str) -> Self {
        Self {
            name,
            pattern: Regex::new(pattern).expect("valid regex in RewriteRule"),
        }
    }
}

/// Outcome of a rewrite attempt.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RewriteResult {
    /// Run `cmd` unchanged.
    Passthrough(String),
    /// Run `rewritten` (which wraps `original` in `sophon exec -- …`).
    Rewritten {
        original: String,
        rewritten: String,
        rule: &'static str,
    },
}

impl RewriteResult {
    pub fn final_command(&self) -> &str {
        match self {
            Self::Passthrough(c) => c,
            Self::Rewritten { rewritten, .. } => rewritten,
        }
    }

    pub fn is_rewritten(&self) -> bool {
        matches!(self, Self::Rewritten { .. })
    }
}

/// Default rule set — 20 regex patterns covering the commands that
/// benefit most from Sophon's output compression.
static DEFAULT_RULES: Lazy<Vec<RewriteRule>> = Lazy::new(|| {
    vec![
        // Git family ---------------------------------------------------------
        RewriteRule::new("git_status", r"^\s*git\s+status\b"),
        RewriteRule::new("git_diff", r"^\s*git\s+diff\b"),
        RewriteRule::new("git_log", r"^\s*git\s+log\b"),
        RewriteRule::new("git_show", r"^\s*git\s+show\b"),
        RewriteRule::new("git_stash_list", r"^\s*git\s+stash\s+list\b"),
        RewriteRule::new("git_branch", r"^\s*git\s+branch\b"),
        RewriteRule::new("git_push", r"^\s*git\s+push\b"),
        RewriteRule::new("git_pull", r"^\s*git\s+pull\b"),
        RewriteRule::new("git_fetch", r"^\s*git\s+fetch\b"),
        // Test runners -------------------------------------------------------
        RewriteRule::new("cargo_test", r"^\s*cargo\s+test\b"),
        RewriteRule::new("pytest", r"^\s*(pytest|python\s+-m\s+pytest)\b"),
        RewriteRule::new("vitest_jest", r"^\s*(vitest|jest|(npm|pnpm|yarn)\s+test)\b"),
        RewriteRule::new("go_test", r"^\s*go\s+test\b"),
        // Build --------------------------------------------------------------
        RewriteRule::new("cargo_build", r"^\s*cargo\s+(build|clippy|check)\b"),
        // Filesystem ---------------------------------------------------------
        RewriteRule::new("ls", r"^\s*ls(\s|$)"),
        RewriteRule::new("tree", r"^\s*tree(\s|$)"),
        RewriteRule::new("find", r"^\s*find\s"),
        RewriteRule::new("grep", r"^\s*(grep|rg|ripgrep|ag|ack)\b"),
        // Docker / Kubernetes -----------------------------------------------
        RewriteRule::new("docker_ps", r"^\s*(docker|podman)\s+(ps|container\s+ls)\b"),
        RewriteRule::new("docker_logs", r"^\s*(docker|podman|kubectl)\s+logs\b"),
    ]
});

/// Pure rewriter. Holds a list of rules and an exclusion prefix list.
#[derive(Debug, Clone)]
pub struct CommandRewriter {
    rules: Vec<RewriteRule>,
    exclusions: Vec<String>,
}

impl Default for CommandRewriter {
    fn default() -> Self {
        Self::new()
    }
}

impl CommandRewriter {
    /// Build a rewriter using the [`DEFAULT_RULES`] set.
    pub fn new() -> Self {
        Self {
            rules: DEFAULT_RULES.clone(),
            exclusions: Vec::new(),
        }
    }

    /// Build a rewriter with an explicit rule list. Used in tests and
    /// when loading a user-provided TOML config.
    pub fn with_rules(rules: Vec<RewriteRule>) -> Self {
        Self {
            rules,
            exclusions: Vec::new(),
        }
    }

    /// Add a prefix that short-circuits to passthrough (e.g. `curl`).
    pub fn exclude<S: Into<String>>(mut self, prefix: S) -> Self {
        self.exclusions.push(prefix.into());
        self
    }

    pub fn rules(&self) -> &[RewriteRule] {
        &self.rules
    }

    /// Attempt to rewrite `command`. Never mutates state; deterministic.
    pub fn rewrite(&self, command: &str) -> RewriteResult {
        let trimmed = command.trim();

        // Already a sophon command → never wrap twice.
        if trimmed.starts_with("sophon ") || trimmed == "sophon" {
            return RewriteResult::Passthrough(command.to_string());
        }

        // User-excluded prefix.
        if self
            .exclusions
            .iter()
            .any(|ex| trimmed.starts_with(ex.as_str()))
        {
            return RewriteResult::Passthrough(command.to_string());
        }

        // Heredoc / multi-line bash block: leave it alone. Wrapping these
        // through `sophon exec --` would be fragile because the `<<` body
        // may contain quoting that breaks argv splitting.
        if trimmed.contains("<<") {
            return RewriteResult::Passthrough(command.to_string());
        }

        // Pipelines: rewriting the first stage is risky (the tail of the
        // pipe might depend on the raw shape). For safety, passthrough.
        if trimmed.contains('|') || trimmed.contains("&&") || trimmed.contains("||") {
            return RewriteResult::Passthrough(command.to_string());
        }

        // Match the first rule whose pattern hits.
        for rule in &self.rules {
            if rule.pattern.is_match(trimmed) {
                let rewritten = format!("sophon exec -- {}", trimmed);
                return RewriteResult::Rewritten {
                    original: command.to_string(),
                    rewritten,
                    rule: rule.name,
                };
            }
        }

        RewriteResult::Passthrough(command.to_string())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn default_rule_count() {
        let r = CommandRewriter::new();
        // 9 git + 4 tests + 1 build + 4 fs + 2 docker = 20
        assert_eq!(r.rules().len(), 20);
    }

    #[test]
    fn rewrites_git_status() {
        let r = CommandRewriter::new();
        let out = r.rewrite("git status");
        assert!(out.is_rewritten());
        assert_eq!(out.final_command(), "sophon exec -- git status");
    }

    #[test]
    fn rewrites_git_diff_with_args() {
        let r = CommandRewriter::new();
        let out = r.rewrite("git diff HEAD~2 src/main.rs");
        assert!(out.is_rewritten());
        assert_eq!(
            out.final_command(),
            "sophon exec -- git diff HEAD~2 src/main.rs"
        );
    }

    #[test]
    fn rewrites_cargo_test() {
        let r = CommandRewriter::new();
        let out = r.rewrite("cargo test --workspace");
        assert!(out.is_rewritten());
        assert_eq!(out.final_command(), "sophon exec -- cargo test --workspace");
    }

    #[test]
    fn rewrites_pytest_and_vitest() {
        let r = CommandRewriter::new();
        assert!(r.rewrite("pytest tests/").is_rewritten());
        assert!(r.rewrite("python -m pytest -xvs").is_rewritten());
        assert!(r.rewrite("vitest run").is_rewritten());
        assert!(r.rewrite("npm test").is_rewritten());
        assert!(r.rewrite("go test ./...").is_rewritten());
    }

    #[test]
    fn rewrites_filesystem_and_search() {
        let r = CommandRewriter::new();
        assert!(r.rewrite("ls -la").is_rewritten());
        assert!(r.rewrite("tree -L 2").is_rewritten());
        assert!(r.rewrite("find . -name '*.rs'").is_rewritten());
        assert!(r.rewrite("grep -rn TODO").is_rewritten());
        assert!(r.rewrite("rg --files").is_rewritten());
    }

    #[test]
    fn rewrites_docker() {
        let r = CommandRewriter::new();
        assert!(r.rewrite("docker ps").is_rewritten());
        assert!(r.rewrite("docker container ls").is_rewritten());
        assert!(r.rewrite("kubectl logs pod-foo").is_rewritten());
    }

    #[test]
    fn passthrough_for_sophon_commands() {
        let r = CommandRewriter::new();
        let out = r.rewrite("sophon serve");
        assert!(!out.is_rewritten(), "should NOT double-wrap sophon");
    }

    #[test]
    fn passthrough_for_heredoc() {
        let r = CommandRewriter::new();
        let out = r.rewrite("cat <<EOF\nhello\nEOF");
        assert!(!out.is_rewritten());
    }

    #[test]
    fn passthrough_for_pipelines() {
        let r = CommandRewriter::new();
        let out = r.rewrite("git log | head -5");
        assert!(!out.is_rewritten(), "pipelines should be left alone");
    }

    #[test]
    fn passthrough_for_unknown_command() {
        let r = CommandRewriter::new();
        let out = r.rewrite("totally_unknown_tool --args");
        assert!(!out.is_rewritten());
        assert_eq!(out.final_command(), "totally_unknown_tool --args");
    }

    #[test]
    fn exclusion_list_wins() {
        let r = CommandRewriter::new().exclude("git log");
        let out = r.rewrite("git log --oneline");
        assert!(
            !out.is_rewritten(),
            "exclusion should short-circuit rewrite"
        );
    }

    #[test]
    fn determinism() {
        let r = CommandRewriter::new();
        let a = r.rewrite("git status");
        let b = r.rewrite("git status");
        assert_eq!(a, b);
    }
}

//! Token-budgeted digest formatter.
//!
//! Given a set of ranked files, build a compact, human-readable
//! summary that fits in a caller-provided token budget. The output is
//! sorted from highest to lowest rank and truncates when the budget
//! runs out.

use serde::{Deserialize, Serialize};
use sophon_core::tokens::count_tokens;

use crate::ranker::RankResult;
use crate::scanner::FileRecord;
use crate::types::{Symbol, SymbolKind};

/// Knobs for [`build_digest`].
#[derive(Debug, Clone)]
pub struct DigestConfig {
    /// Soft ceiling on output tokens. We stop adding files (or
    /// symbols within a file) once this is reached.
    pub max_tokens: usize,
    /// Max symbols per file in the output, to keep any single file
    /// from dominating a small budget.
    pub max_symbols_per_file: usize,
    /// Skip files whose computed rank is below this threshold.
    pub min_rank: f32,
}

impl Default for DigestConfig {
    fn default() -> Self {
        Self {
            max_tokens: 1500,
            max_symbols_per_file: 20,
            min_rank: 0.0,
        }
    }
}

/// Serialisable representation of what we hand back to the caller.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Digest {
    pub rendered: String,
    pub files: Vec<FileDigest>,
    pub total_files_scanned: usize,
    pub total_symbols_found: usize,
    pub total_tokens: usize,
    pub edges_in_graph: usize,
    pub query: Option<String>,
    pub truncated: bool,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct FileDigest {
    pub path: String,
    pub rank: f32,
    pub symbols: Vec<SymbolLine>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SymbolLine {
    pub kind: SymbolKind,
    pub name: String,
    pub line: u32,
    pub signature: String,
}

impl From<&Symbol> for SymbolLine {
    fn from(s: &Symbol) -> Self {
        Self {
            kind: s.kind,
            name: s.name.clone(),
            line: s.line,
            signature: s.signature.clone(),
        }
    }
}

/// Build a digest from scanned records and their ranks. The `records`
/// and `rank_result.ranks` must line up index-for-index.
pub fn build_digest(
    records: &[FileRecord],
    rank_result: &RankResult,
    query: Option<&str>,
    config: &DigestConfig,
) -> Digest {
    assert_eq!(records.len(), rank_result.ranks.len());

    let total_symbols: usize = records.iter().map(|r| r.symbols.len()).sum();

    // Pair each file with its rank, then sort descending by rank.
    let mut by_rank: Vec<(usize, f32)> = rank_result
        .ranks
        .iter()
        .enumerate()
        .map(|(i, r)| (i, *r))
        .collect();
    by_rank.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap_or(std::cmp::Ordering::Equal));

    let mut files_out: Vec<FileDigest> = Vec::new();
    let mut rendered = String::new();
    let mut total_tokens = 0usize;
    let mut truncated = false;

    if let Some(q) = query {
        rendered.push_str(&format!("# Codebase digest (query: {:?})\n", q));
    } else {
        rendered.push_str("# Codebase digest\n");
    }
    rendered.push_str(&format!(
        "# {} files scanned, {} symbols, {} graph edges\n\n",
        records.len(),
        total_symbols,
        rank_result.edge_count
    ));
    total_tokens += count_tokens(&rendered);

    for (idx, rank) in by_rank {
        if rank < config.min_rank {
            continue;
        }
        if total_tokens >= config.max_tokens {
            truncated = true;
            break;
        }

        let rec = &records[idx];
        if rec.symbols.is_empty() {
            continue;
        }

        // Header for the file.
        let header = format!("## {}  (rank {:.4})\n", rec.relative_path, rank);
        let header_tokens = count_tokens(&header);
        if total_tokens + header_tokens > config.max_tokens {
            truncated = true;
            break;
        }
        rendered.push_str(&header);
        total_tokens += header_tokens;

        let mut file_symbols: Vec<SymbolLine> = Vec::new();
        let mut symbol_count = 0;
        for sym in &rec.symbols {
            if symbol_count >= config.max_symbols_per_file {
                break;
            }
            let line_text = format!(
                "  L{:<5} {:<9} {}\n",
                sym.line,
                sym.kind.as_str(),
                sym.signature
            );
            let line_tokens = count_tokens(&line_text);
            if total_tokens + line_tokens > config.max_tokens {
                truncated = true;
                break;
            }
            rendered.push_str(&line_text);
            total_tokens += line_tokens;
            file_symbols.push(SymbolLine::from(sym));
            symbol_count += 1;
        }
        rendered.push('\n');
        total_tokens += 1;

        files_out.push(FileDigest {
            path: rec.relative_path.clone(),
            rank,
            symbols: file_symbols,
        });

        if truncated {
            break;
        }
    }

    if truncated {
        rendered.push_str("... digest truncated at token budget ...\n");
        total_tokens += count_tokens("... digest truncated at token budget ...");
    }

    Digest {
        rendered,
        files: files_out,
        total_files_scanned: records.len(),
        total_symbols_found: total_symbols,
        total_tokens,
        edges_in_graph: rank_result.edge_count,
        query: query.map(|s| s.to_string()),
        truncated,
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::ranker::rank_files;
    use crate::types::{Symbol, SymbolKind};

    fn file(path: &str, content: &str, symbols: Vec<(&str, SymbolKind)>) -> FileRecord {
        FileRecord {
