use std::{fs, io::Write, path::Path};

use differ::generate_diff;
use protocol::{FileChanges, FileReadResponse, FileWriteRequest};
use sophon_core::{
    error::SophonError,
    hashing::{hash_content, hash_lines},
    tokens::count_tokens,
};
use state::{FileState, StateStore};

/// Delta streamer engine that serves delta-aware file read/write operations.
#[derive(Debug)]
pub struct DeltaStreamer {
    state: StateStore,
}

impl DeltaStreamer {
    pub fn new(max_files: usize) -> Self {
        Self {
            state: StateStore::new(max_files),
        }
    }

    pub fn read_file_delta<P: AsRef<Path>>(
        &mut self,
        path: P,
        known_version: Option<u64>,
        known_hash: Option<&str>,
    ) -> Result<FileReadResponse, SophonError> {
        let path_buf = path.as_ref().to_path_buf();
        if !path_buf.exists() {
            return Err(SophonError::file_not_found(path_buf));
        }

        let content = fs::read_to_string(&path_buf)?;
        let hash = hash_content(&content);
        let token_count = count_tokens(&content);

        // Stateless-resume: honor client-provided known_hash even if we have
        // no prior state for this path (in-memory store is lost across runs).
        if self.state.get(&path_buf).is_none() {
            if let Some(kh) = known_hash {
                if kh == hash {
                    let version = known_version.unwrap_or(1);
                    self.state.insert(FileState {
                        path: path_buf.clone(),
                        hash: hash.clone(),
                        version,
                        line_hashes: hash_lines(&content),
                        content: content.clone(),
                        token_count,
                    });
                    return Ok(FileReadResponse::Unchanged { version, hash });
                }
            }
        }

        if let Some(existing) = self.state.get(&path_buf).cloned() {
            if known_hash.map(|h| h == existing.hash).unwrap_or(false)
                || known_version
                    .map(|v| v == existing.version)
                    .unwrap_or(false)
            {
                if existing.hash == hash {
                    self.state.touch(&path_buf);
                    return Ok(FileReadResponse::Unchanged {
                        version: existing.version,
                        hash,
                    });
                }

                let operations = generate_diff(&existing.content, &content);
                let new_state = FileState {
                    path: path_buf.clone(),
                    hash: hash.clone(),
                    version: existing.version + 1,
                    line_hashes: hash_lines(&content),
                    content: content.clone(),
                    token_count,
                };
                self.state.insert(new_state.clone());

                let delta_tokens = count_tokens(&format!("{:?}", operations));
                return Ok(FileReadResponse::Delta {
                    base_version: existing.version,
                    new_version: new_state.version,
                    new_hash: hash,
                    operations,
                    token_count: delta_tokens,
                });
            }

            // Known version/hash doesn't match or wasn't provided.
            if existing.hash == hash {
                self.state.touch(&path_buf);
                return Ok(FileReadResponse::Full {
                    content,
                    version: existing.version,
                    hash,
                    token_count,
                });
            }

            let updated = FileState {
                path: path_buf.clone(),
                hash: hash.clone(),
                version: existing.version + 1,
                line_hashes: hash_lines(&content),
                content: content.clone(),
                token_count,
            };
            self.state.insert(updated.clone());
            return Ok(FileReadResponse::Full {
                content,
                version: updated.version,
                hash,
                token_count,
            });
        }

        let state = FileState {
            path: path_buf.clone(),
            hash: hash.clone(),
            version: 1,
            line_hashes: hash_lines(&content),
            content: content.clone(),
            token_count,
        };
        self.state.insert(state.clone());

        Ok(FileReadResponse::Full {
            content,
            version: state.version,
            hash,
            token_count,
        })
    }

    pub fn write_file_delta(
        &mut self,
        request: FileWriteRequest,
    ) -> Result<FileReadResponse, SophonError> {
        use patcher::{apply_diff, apply_structured_edits};

        let path = request.path;
        let existing_content = if path.exists() {
            fs::read_to_string(&path)?
        } else {
            String::new()
        };

        let current_state = self.state.get(&path).cloned();
        let current_version = current_state.as_ref().map(|s| s.version).unwrap_or(0);

        let new_content = match request.changes {
            FileChanges::Full { content } => content,
            FileChanges::Delta {
                base_version,
                operations,
            } => {
                if base_version != current_version {
                    return Err(SophonError::version_mismatch(current_version, base_version));
                }
                apply_diff(&existing_content, &operations)
                    .map_err(|e| SophonError::parse(e.to_string()))?
            }
            FileChanges::Structured { edits } => apply_structured_edits(&existing_content, &edits)
                .map_err(|e| SophonError::parse(e.to_string()))?,
        };

        if let Some(parent) = path.parent() {
            fs::create_dir_all(parent)?;
        }
        atomic_write(&path, new_content.as_bytes())?;

        let hash = hash_content(&new_content);
        let token_count = count_tokens(&new_content);
        let new_version = current_version + 1;

        self.state.insert(FileState {
            path: path.clone(),
            hash: hash.clone(),
            version: new_version,
            line_hashes: hash_lines(&new_content),
            content: new_content.clone(),
            token_count,
        });

        Ok(FileReadResponse::Full {
            content: new_content,
            version: new_version,
            hash,
            token_count,
        })
    }

    pub fn state_store(&self) -> &StateStore {
        &self.state
    }
}

/// Atomic write: stage to a sibling temp file, fsync, then rename.
/// `rename` is atomic on the same filesystem, so readers see either the
/// old or the new content — never a partially-written file.
fn atomic_write(path: &Path, bytes: &[u8]) -> Result<(), SophonError> {
    let parent = path.parent().unwrap_or_else(|| Path::new("."));
    let file_name = path
        .file_name()
        .ok_or_else(|| SophonError::parse("path has no file name".to_string()))?
        .to_string_lossy();
    let nonce = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_nanos())
        .unwrap_or(0);
    let tmp = parent.join(format!(
        ".{}.sophon-{}-{}.tmp",
        file_name,
        std::process::id(),
        nonce
    ));

    let mut f = fs::File::create(&tmp)?;
    f.write_all(bytes)?;
    f.sync_all()?;
    drop(f);

    if let Err(e) = fs::rename(&tmp, path) {
        let _ = fs::remove_file(&tmp);
        return Err(e.into());
    }
    Ok(())
}

use regex::Regex;

use crate::{
    differ::DiffOperation,
    protocol::{EditAnchor, EditOperation, StructuredEdit, SymbolKind},
};

#[derive(Debug, thiserror::Error)]
pub enum PatchError {
    #[error("Invalid line range: start={start}, count={count}, total={total}")]
    InvalidRange {
        start: usize,
        count: usize,
        total: usize,
    },
}

#[derive(Debug, thiserror::Error)]
pub enum EditError {
    #[error("Anchor not found: {0}")]
    AnchorNotFound(String),

    #[error("Anchor not unique: {0}")]
    AnchorNotUnique(String),

    #[error("Invalid line range: {0}-{1}")]
    InvalidLineRange(usize, usize),
}

/// Apply diff operations to content.
pub fn apply_diff(base: &str, operations: &[DiffOperation]) -> Result<String, PatchError> {
    let (mut lines, had_trailing_newline) = split_lines(base);

    // Apply non-keep operations from bottom to top to avoid index-shift issues.
    let mut indexed_ops = operations
        .iter()
        .enumerate()
        .filter(|(_, op)| !matches!(op, DiffOperation::Keep { .. }))
        .collect::<Vec<_>>();

    indexed_ops.sort_by(|(_, a), (_, b)| op_position(b).cmp(&op_position(a)));

    for (_, op) in indexed_ops {
        match op {
            DiffOperation::Keep { .. } => {}
            DiffOperation::Delete { start, count } => {
                let idx = start.saturating_sub(1);
                if idx + count > lines.len() {
                    return Err(PatchError::InvalidRange {
                        start: *start,
                        count: *count,
                        total: lines.len(),
                    });
                }
                lines.drain(idx..idx + count);
            }
            DiffOperation::Insert {
                at,
                lines: new_lines,
            } => {
                let idx = at.saturating_sub(1).min(lines.len());
                for (offset, line) in new_lines.iter().enumerate() {
                    lines.insert(idx + offset, line.clone());
                }
            }
            DiffOperation::Replace {
                start,
                delete_count,
                new_lines,
            } => {
                let idx = start.saturating_sub(1);
                if idx + delete_count > lines.len() {
                    return Err(PatchError::InvalidRange {
                        start: *start,
                        count: *delete_count,
                        total: lines.len(),
                    });
                }

                lines.splice(idx..idx + delete_count, new_lines.iter().cloned());
            }
        }
    }

    Ok(join_lines(&lines, had_trailing_newline))
}

/// Apply structured edits (safer than raw diff).
pub fn apply_structured_edits(
    content: &str,
    edits: &[StructuredEdit],
) -> Result<String, EditError> {
    let (mut lines, had_trailing_newline) = split_lines(content);

    let mut resolved = Vec::new();
    for edit in edits {
        let (start, end) = resolve_anchor(&lines, &edit.anchor)?;
        resolved.push((start, end, edit.operation.clone()));
    }

    resolved.sort_by(|(a_start, _, _), (b_start, _, _)| b_start.cmp(a_start));

    for (start, end, operation) in resolved {
        let start_idx = start.saturating_sub(1);
        let end_idx = end.min(lines.len());

        match operation {
            EditOperation::Replace { new_content } => {
                let replacement = new_content
                    .lines()
                    .map(|line| line.to_string())
                    .collect::<Vec<_>>();
                if start_idx > end_idx || end_idx > lines.len() {
                    return Err(EditError::InvalidLineRange(start, end));
                }
                lines.splice(start_idx..end_idx, replacement);
            }
            EditOperation::InsertBefore { content } => {
                let insert = content
                    .lines()
                    .map(|line| line.to_string())
                    .collect::<Vec<_>>();
                if start_idx > lines.len() {
                    return Err(EditError::InvalidLineRange(start, end));
                }
                for (offset, line) in insert.into_iter().enumerate() {
                    lines.insert(start_idx + offset, line);
                }
            }
            EditOperation::InsertAfter { content } => {
                let insert = content
                    .lines()
                    .map(|line| line.to_string())
                    .collect::<Vec<_>>();
                let at = end_idx.min(lines.len());
                for (offset, line) in insert.into_iter().enumerate() {
                    lines.insert(at + offset, line);
                }
            }
            EditOperation::Delete => {
                if start_idx > end_idx || end_idx > lines.len() {
                    return Err(EditError::InvalidLineRange(start, end));
                }
                lines.drain(start_idx..end_idx);
            }
        }
    }

    Ok(join_lines(&lines, had_trailing_newline))
}

fn resolve_anchor(lines: &[String], anchor: &EditAnchor) -> Result<(usize, usize), EditError> {
    match anchor {
        EditAnchor::LineRange { start, end } => {
            if *start == 0 || *start > *end || *end > lines.len() {
                return Err(EditError::InvalidLineRange(*start, *end));
            }
            Ok((*start, *end))
        }
        EditAnchor::UniqueText { text } => {
            let matches = lines
                .iter()
                .enumerate()
                .filter(|(_, line)| line.contains(text))
                .map(|(idx, _)| idx + 1)
                .collect::<Vec<_>>();

            match matches.as_slice() {
                [single] => Ok((*single, *single)),
                [] => Err(EditError::AnchorNotFound(text.clone())),
                _ => Err(EditError::AnchorNotUnique(text.clone())),
            }
        }
        EditAnchor::Symbol { name, kind } => resolve_symbol(lines, name, kind),
    }
}

fn resolve_symbol(
    lines: &[String],
    name: &str,
    kind: &SymbolKind,
) -> Result<(usize, usize), EditError> {
    let pattern = match kind {
        SymbolKind::Function => format!(
            r"^\s*(?:pub\s+)?(?:async\s+)?fn\s+{}\b",
            regex::escape(name)
        ),
        SymbolKind::Class => format!(r"^\s*class\s+{}\b", regex::escape(name)),
        SymbolKind::Struct => format!(r"^\s*(?:pub\s+)?struct\s+{}\b", regex::escape(name)),
        SymbolKind::Enum => format!(r"^\s*(?:pub\s+)?enum\s+{}\b", regex::escape(name)),
    };

    let re = Regex::new(&pattern).map_err(|_| EditError::AnchorNotFound(name.to_string()))?;
    for (idx, line) in lines.iter().enumerate() {
        if re.is_match(line) {
            let end = find_block_end(lines, idx + 1);
            return Ok((idx + 1, end));
        }
    }

    Err(EditError::AnchorNotFound(name.to_string()))
}

fn find_block_end(lines: &[String], start_line: usize) -> usize {
    let mut balance = 0i32;
    let mut seen_brace = false;

    for (idx, line) in lines.iter().enumerate().skip(start_line - 1) {
        for c in line.chars() {
            if c == '{' {
                balance += 1;
                seen_brace = true;
            } else if c == '}' {
                balance -= 1;
            }
        }

        if seen_brace && balance <= 0 {
            return idx + 1;
        }
    }

    start_line
}

fn split_lines(content: &str) -> (Vec<String>, bool) {
    let trailing = content.ends_with('\n');
    let lines = content
        .lines()
        .map(|line| line.to_string())
        .collect::<Vec<_>>();
    (lines, trailing)
}

fn join_lines(lines: &[String], trailing_newline: bool) -> String {
    if lines.is_empty() {
        return if trailing_newline {
            "\n".to_string()
        } else {
            String::new()
        };
    }

    let mut out = lines.join("\n");
    if trailing_newline {
        out.push('\n');
    }
    out
}

fn op_position(op: &DiffOperation) -> usize {
    match op {
        DiffOperation::Keep { start, .. } => *start,
        DiffOperation::Delete { start, .. } => *start,
        DiffOperation::Insert { at, .. } => *at,
        DiffOperation::Replace { start, .. } => *start,
    }
}

use std::collections::{HashMap, HashSet};

use regex::Regex;

use crate::store::{Fragment, FragmentCategory};

#[derive(Debug, Clone)]
pub struct DetectedFragment {
    pub content: String,
    pub category: FragmentCategory,
    pub confidence: f32,
}

impl DetectedFragment {
    pub fn into_fragment(self) -> Fragment {
        let tags = vec![format!("confidence:{:.2}", self.confidence)];
        Fragment::from_content(self.content, self.category, tags)
    }
}

pub const BOILERPLATE_SIGNATURES: &[(&str, FragmentCategory)] = &[
    ("import React", FragmentCategory::CodeBoilerplate),
    ("from typing import", FragmentCategory::CodeBoilerplate),
    ("#[derive(", FragmentCategory::CodeBoilerplate),
    ("\"$schema\":", FragmentCategory::DataStructure),
    ("export default function", FragmentCategory::CodeBoilerplate),
];

/// Detect potentially reusable fragments in content.
pub fn detect_fragments(content: &str, min_tokens: usize) -> Vec<DetectedFragment> {
    let mut detected = Vec::new();

    let code_block_regex = Regex::new(r"```[\w]*\n([\s\S]+?)```").expect("valid regex");
    for cap in code_block_regex.captures_iter(content) {
        let block = cap.get(1).map(|m| m.as_str()).unwrap_or_default();
        if sophon_core::tokens::count_tokens(block) >= min_tokens {
            detected.push(DetectedFragment {
                content: block.to_string(),
                category: FragmentCategory::CodeBoilerplate,
                confidence: 0.8,
            });
        }
    }

    detected.extend(detect_repeated_patterns(content, min_tokens));

    // Near-duplicate pre-pass: catch paragraphs that differ only by a number
    // or minor token variation (Jaccard >= 0.95).
    detected.extend(detect_near_duplicates(content, min_tokens, 0.95));

    for (signature, category) in BOILERPLATE_SIGNATURES {
        if content.contains(signature) {
            detected.push(DetectedFragment {
                content: signature.to_string(),
                category: *category,
                confidence: 0.65,
            });
        }
    }

    dedupe_detected(detected)
}

fn detect_repeated_patterns(content: &str, min_tokens: usize) -> Vec<DetectedFragment> {
    // Split into paragraphs (blank-line delimited) and slide a window of
    // 1..=max_window consecutive paragraphs. `max_window` used to be a hard
    // const of 12 — now it adapts to the paragraph count so that documents
    // with many small paragraphs can still detect large repeated blocks
    // (up to half of the document, bounded to 64 to keep the O(P² × C) work
    // reasonable). Callers who want stricter control can set
    // SOPHON_FRAGMENT_MAX_WINDOW in the environment.
    const HARD_CAP: usize = 64;

    let paragraphs: Vec<&str> = content
        .split("\n\n")
        .map(|p| p.trim_matches('\n'))
        .filter(|p| !p.trim().is_empty())
        .collect();

    if paragraphs.is_empty() {
        return Vec::new();
    }

    let max_window: usize = std::env::var("SOPHON_FRAGMENT_MAX_WINDOW")
        .ok()
        .and_then(|s| s.parse().ok())
        .unwrap_or_else(|| (paragraphs.len() / 2).clamp(12, HARD_CAP));

    // Collect candidate blocks (content, token_count) that occur at least
    // twice in the original text.
    let mut candidates: Vec<(String, usize)> = Vec::new();

    for start in 0..paragraphs.len() {
        let upper = (start + max_window).min(paragraphs.len());
        for end in (start + 1)..=upper {
            let block = paragraphs[start..end].join("\n\n");
            let tokens = sophon_core::tokens::count_tokens(&block);
            if tokens < min_tokens {
                // Smaller windows starting here only get smaller; but we need
                // to keep growing because tokens may accumulate across paragraphs.
                continue;
            }
            // Count non-overlapping occurrences in the raw content.
            let occurrences = count_non_overlapping(content, &block);
            if occurrences >= 2 {
                candidates.push((block, tokens));
            }
        }
    }

    if candidates.is_empty() {
        // Fall back to the original single-paragraph pass for short repeats.
        let mut counts: HashMap<String, usize> = HashMap::new();
        for p in &paragraphs {
            *counts.entry((*p).to_string()).or_insert(0) += 1;
        }
        return counts
            .into_iter()
            .filter(|(frag, count)| {
                *count >= 2 && sophon_core::tokens::count_tokens(frag) >= min_tokens
            })
            .map(|(frag, _)| DetectedFragment {
                content: frag,
                category: FragmentCategory::Template,
                confidence: 0.7,
            })
            .collect();
    }

    // Dedup overlapping candidates: prefer the largest block, drop any candidate
    // that is wholly contained in an already-kept block (and vice versa).
    candidates.sort_by(|a, b| b.1.cmp(&a.1));
    let mut kept: Vec<(String, usize)> = Vec::new();
    for (block, tokens) in candidates {
        let overlaps = kept
            .iter()
            .any(|(k, _)| k.contains(&block) || block.contains(k));
        if !overlaps {
            kept.push((block, tokens));
        }
    }

    kept.into_iter()
        .map(|(block, _)| DetectedFragment {
            content: block,
            category: FragmentCategory::Template,
            confidence: 0.75,
        })
        .collect()
}

/// Count how many times `needle` occurs in `haystack` without overlap.
fn count_non_overlapping(haystack: &str, needle: &str) -> usize {
    if needle.is_empty() {
        return 0;
    }
    let mut count = 0;
    let mut start = 0;
    while let Some(pos) = haystack[start..].find(needle) {
        count += 1;
        start += pos + needle.len();
    }
    count
}

/// Jaccard similarity over whitespace tokens.
fn jaccard(a: &str, b: &str) -> f32 {
    let ta: HashSet<&str> = a.split_whitespace().collect();
    let tb: HashSet<&str> = b.split_whitespace().collect();
    if ta.is_empty() && tb.is_empty() {
        return 1.0;
    }
    let inter = ta.intersection(&tb).count() as f32;
    let union = ta.union(&tb).count() as f32;
    if union == 0.0 {
        0.0
    } else {
        inter / union
    }
}

/// Near-duplicate detection: for each unique paragraph, check Jaccard
/// similarity against other paragraphs. If similarity >= threshold, treat
/// the first occurrence as a reusable fragment.
fn detect_near_duplicates(
    content: &str,
    min_tokens: usize,
    threshold: f32,
) -> Vec<DetectedFragment> {
    let paragraphs: Vec<&str> = content
        .split("\n\n")
        .map(|p| p.trim())
        .filter(|p| !p.is_empty())
        .collect();

    if paragraphs.len() < 2 {
        return Vec::new();
    }

    let mut detected = Vec::new();
    let mut used: HashSet<usize> = HashSet::new();

    for i in 0..paragraphs.len() {
        if used.contains(&i) {
            continue;
        }
        let tokens_i = sophon_core::tokens::count_tokens(paragraphs[i]);
        if tokens_i < min_tokens {
            continue;
        }
        let mut has_near_dup = false;
        for j in (i + 1)..paragraphs.len() {
            if used.contains(&j) {
                continue;
            }
            // Skip exact matches — those are handled by the existing pass.
            if paragraphs[i] == paragraphs[j] {
                continue;
            }
            if jaccard(paragraphs[i], paragraphs[j]) >= threshold {
                has_near_dup = true;
                used.insert(j);
            }
        }
        if has_near_dup {
            used.insert(i);
            detected.push(DetectedFragment {
                content: paragraphs[i].to_string(),
                category: FragmentCategory::Template,
                confidence: 0.72,
            });
        }
    }

    detected
}

fn dedupe_detected(detected: Vec<DetectedFragment>) -> Vec<DetectedFragment> {
    let mut seen = HashMap::<String, DetectedFragment>::new();
    for item in detected {
        let key = item.content.clone();
        let replace = match seen.get(&key) {
            Some(existing) => item.confidence > existing.confidence,
            None => true,
        };
        if replace {
            seen.insert(key, item);
        }
    }
    seen.into_values().collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn near_duplicate_paragraphs_detected() {
        // Two paragraphs that differ only by a single number should be
        // caught as near-duplicates (Jaccard >= 0.95). The paragraph must
        // be long enough that one differing token keeps Jaccard above 0.95.
        // With ~40 shared tokens and 1 differing, Jaccard = 40/42 ≈ 0.952.
        let shared = "The quick brown fox jumped over the lazy dog and then \
                       ran across the wide open meadow before stopping at the \
                       edge of the forest where the tall oak trees swayed gently \
                       in the warm afternoon breeze while birds sang their songs";
        let content = format!("{shared} item 1\n\n{shared} item 2");
        let detected = detect_fragments(&content, 1);
        let near_dup = detected.iter().find(|d| d.content.contains("item 1"));
        assert!(
            near_dup.is_some(),
            "expected near-duplicate detection for paragraphs differing by a single number, got: {:?}",
            detected,
        );
    }

    #[test]
    fn exact_duplicates_still_detected() {
        let content = "repeated paragraph here\n\nrepeated paragraph here";
        let detected = detect_fragments(content, 1);
        assert!(
            !detected.is_empty(),
            "exact duplicates should still be detected",
        );
    }

    #[test]
    fn dissimilar_paragraphs_not_flagged() {
        let content = "The quick brown fox jumped over the lazy dog.\n\n\
                        A completely different sentence about unrelated topics.";
        let detected = detect_near_duplicates(content, 1, 0.95);
        assert!(
            detected.is_empty(),
            "dissimilar paragraphs should not be flagged as near-duplicates, got: {:?}",
            detected,
        );
    }

    #[test]
    fn jaccard_identical_strings() {
        assert!((jaccard("a b c", "a b c") - 1.0).abs() < f32::EPSILON);
    }

    #[test]
    fn jaccard_disjoint_strings() {
        assert!((jaccard("a b c", "x y z")).abs() < f32::EPSILON);
    }
}

use crate::{
    detector::detect_fragments,
    store::{Fragment, FragmentStore},
};

#[derive(Debug, Clone, serde::Deserialize)]
#[serde(default)]
pub struct EncoderConfig {
    pub min_fragment_tokens: usize,
    pub auto_detect: bool,
    pub max_replacement_ratio: f32,
}

impl Default for EncoderConfig {
    fn default() -> Self {
        Self {
            min_fragment_tokens: 50,
            auto_detect: true,
            max_replacement_ratio: 0.7,
        }
    }
}

#[derive(Debug, Clone)]
pub struct EncodedContent {
    pub content: String,
    pub used_fragments: Vec<String>,
    pub new_fragments: Vec<Fragment>,
    pub token_count: usize,
    pub tokens_saved: usize,
}

/// Encode content by replacing fragments with references.
pub fn encode_content(
    content: &str,
    store: &FragmentStore,
    config: &EncoderConfig,
) -> EncodedContent {
    let mut result = content.to_string();
    let mut used_fragments = Vec::new();
    let mut tokens_saved = 0usize;

    let original_tokens = sophon_core::tokens::count_tokens(content);
    let max_replace_tokens = (original_tokens as f32 * config.max_replacement_ratio) as usize;
    let mut replaced_tokens = 0usize;

    let mut stored_fragments = store.iter().collect::<Vec<_>>();
    stored_fragments.sort_by(|a, b| b.token_count.cmp(&a.token_count));

    // Detect new fragments up front so we can apply them on the SAME call
    // (previously the first call was always a no-op: store empty → nothing
    // replaced → fragments added to store but original content returned).
    let new_fragments: Vec<Fragment> = if config.auto_detect {
        detect_fragments(content, config.min_fragment_tokens)
            .into_iter()
            .filter(|d| !store.contains_hash(&sophon_core::hashing::hash_content(&d.content)))
            .map(|d| d.into_fragment())
            .collect()
    } else {
        Vec::new()
    };

    // Merge stored + new into a single pass, largest-first. Using references
    // so we don't clone Fragments twice.
    let mut all_fragments: Vec<&Fragment> = stored_fragments;
    all_fragments.extend(new_fragments.iter());
    all_fragments.sort_by(|a, b| b.token_count.cmp(&a.token_count));

    for fragment in all_fragments {
        if !result.contains(&fragment.content) {
            continue;
        }

        let ref_str = format!("[FRAGMENT:{}]", fragment.id);
        let ref_tokens = sophon_core::tokens::count_tokens(&ref_str);
        let per_occurrence_savings = fragment.token_count.saturating_sub(ref_tokens);

        if per_occurrence_savings == 0 {
            continue;
        }

        if replaced_tokens + fragment.token_count > max_replace_tokens && !used_fragments.is_empty()
        {
            continue;
        }

        // Count occurrences BEFORE replacement so savings accounting reflects
        // the full win (String::replace replaces all occurrences at once).
        let occurrences = result.matches(&fragment.content).count();
        if occurrences == 0 {
            continue;
        }

        result = result.replace(&fragment.content, &ref_str);
        used_fragments.push(fragment.id.clone());
        tokens_saved += per_occurrence_savings * occurrences;
        replaced_tokens += fragment.token_count;
    }

    EncodedContent {
        token_count: sophon_core::tokens::count_tokens(&result),
        content: result,
        used_fragments,
        new_fragments,
        tokens_saved,
    }
}

use std::{
    collections::HashMap,
    fs,
    path::{Path, PathBuf},
};

use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};
use sophon_core::{hashing::hash_content, tokens::count_tokens};
use uuid::Uuid;

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Fragment {
    pub id: String,
    pub content: String,
    pub hash: String,
    pub token_count: usize,
    pub use_count: u64,
    pub created_at: DateTime<Utc>,
    pub last_used: DateTime<Utc>,
    pub category: FragmentCategory,
    pub tags: Vec<String>,
}

impl Default for Fragment {
    fn default() -> Self {
        let now = Utc::now();
        Self {
            id: Uuid::new_v4().to_string(),
            content: String::new(),
            hash: String::new(),
            token_count: 0,
            use_count: 0,
            created_at: now,
            last_used: now,
            category: FragmentCategory::Template,
            tags: vec![],
        }
    }
}

impl Fragment {
    pub fn from_content(content: String, category: FragmentCategory, tags: Vec<String>) -> Self {
        let now = Utc::now();
        Self {
            id: Uuid::new_v4().to_string(),
            token_count: count_tokens(&content),
            hash: hash_content(&content),
            content,
            use_count: 0,
            created_at: now,
            last_used: now,
            category,
            tags,
        }
    }
}

#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Eq)]
pub enum FragmentCategory {
    CodeBoilerplate,
    SystemInstruction,
    DataStructure,
    Template,
    Definition,
}

#[derive(Debug)]
pub struct FragmentStore {
    fragments: HashMap<String, Fragment>,
    hash_index: HashMap<String, String>,
    storage_path: PathBuf,
    max_fragments: usize,
}

impl FragmentStore {
    pub fn new_memory() -> Self {
        Self {
            fragments: HashMap::new(),
            hash_index: HashMap::new(),
            storage_path: PathBuf::new(),
            max_fragments: 1_000,
        }
    }

    pub fn new(
        storage_path: impl AsRef<Path>,
        max_fragments: usize,
    ) -> Result<Self, std::io::Error> {
        let path = storage_path.as_ref().to_path_buf();
        let mut store = Self {
            fragments: HashMap::new(),
            hash_index: HashMap::new(),
            storage_path: path,
            max_fragments: max_fragments.max(1),
        };
        store.load()?;
        Ok(store)
    }

    pub fn load(&mut self) -> Result<(), std::io::Error> {
        if self.storage_path.as_os_str().is_empty() || !self.storage_path.exists() {
            return Ok(());
        }

        let raw = fs::read_to_string(&self.storage_path)?;
        let list: Vec<Fragment> = serde_json::from_str(&raw).unwrap_or_default();

        self.fragments.clear();
        self.hash_index.clear();

        for fragment in list {
            self.hash_index
                .insert(fragment.hash.clone(), fragment.id.clone());
            self.fragments.insert(fragment.id.clone(), fragment);
        }

        Ok(())
    }

    pub fn save(&self) -> Result<(), std::io::Error> {
        if self.storage_path.as_os_str().is_empty() {
            return Ok(());
        }
        if let Some(parent) = self.storage_path.parent() {
            fs::create_dir_all(parent)?;
        }

        let mut list = self.fragments.values().cloned().collect::<Vec<_>>();
        list.sort_by(|a, b| b.use_count.cmp(&a.use_count));
        let raw = serde_json::to_string_pretty(&list).unwrap_or_else(|_| "[]".to_string());
        fs::write(&self.storage_path, raw)
    }

    pub fn add(&mut self, mut fragment: Fragment) -> String {
        if let Some(existing_id) = self.hash_index.get(&fragment.hash).cloned() {
            self.touch(&existing_id);
            return existing_id;
        }

        fragment.last_used = Utc::now();
        let id = fragment.id.clone();
        self.hash_index.insert(fragment.hash.clone(), id.clone());
        self.fragments.insert(id.clone(), fragment);
        self.evict_if_needed();
        let _ = self.save();
        id
    }

    pub fn get(&self, id: &str) -> Option<&Fragment> {
        self.fragments.get(id)
    }

    pub fn touch(&mut self, id: &str) {
        if let Some(fragment) = self.fragments.get_mut(id) {
            fragment.use_count += 1;
            fragment.last_used = Utc::now();
        }
    }

    pub fn contains_hash(&self, hash: &str) -> bool {
        self.hash_index.contains_key(hash)
    }

    pub fn iter(&self) -> impl Iterator<Item = &Fragment> {
        self.fragments.values()
    }

    pub fn len(&self) -> usize {
        self.fragments.len()
    }

    fn evict_if_needed(&mut self) {
        if self.fragments.len() <= self.max_fragments {
            return;
        }

        let mut fragments = self.fragments.values().cloned().collect::<Vec<_>>();
        fragments.sort_by(|a, b| a.last_used.cmp(&b.last_used));

        while self.fragments.len() > self.max_fragments {
            if let Some(fragment) = fragments.first() {
                self.hash_index.remove(&fragment.hash);
                self.fragments.remove(&fragment.id);
                fragments.remove(0);
            } else {
                break;
            }
        }
    }
}

//! JSON-RPC 2.0 error helpers for the MCP stdio server.
//!
//! The MCP spec (2025-06-18) inherits JSON-RPC 2.0's error model. We map
//! internal failure modes to structured `{code, message, data?}` objects
//! instead of bubbling raw `anyhow::Error::to_string()` strings, so
//! clients can branch on the code rather than regex-matching English.
//!
//! ## Code ranges
//!
//! | Range              | Source                            |
//! |--------------------|-----------------------------------|
//! | -32700             | Parse error (JSON-RPC reserved)   |
//! | -32600             | Invalid Request                   |
//! | -32601             | Method not found                  |
//! | -32602             | Invalid params                    |
//! | -32603             | Internal error                    |
//! | -32000 .. -32099   | Server-defined (Sophon)           |
//!
//! Only the `-32000..-32099` range is ours to define. See
//! <https://www.jsonrpc.org/specification#error_object>.

use serde_json::{json, Value};

/// Standard JSON-RPC 2.0 error codes.
pub const PARSE_ERROR: i32 = -32700;
pub const INVALID_REQUEST: i32 = -32600;
pub const METHOD_NOT_FOUND: i32 = -32601;
pub const INVALID_PARAMS: i32 = -32602;
pub const INTERNAL_ERROR: i32 = -32603;

/// Sophon-defined server error codes (JSON-RPC 2.0 reserves -32000..-32099
/// for implementation-specific server errors). These are stable — clients
/// can match on them. New codes go at the end; never renumber existing
/// ones without a protocol version bump.
pub const SOPHON_TOOL_NOT_FOUND: i32 = -32001;
pub const SOPHON_TOOL_ARGUMENTS_INVALID: i32 = -32002;
pub const SOPHON_TOOL_EXECUTION_FAILED: i32 = -32003;
pub const SOPHON_RETRIEVER_UNAVAILABLE: i32 = -32004;
pub const SOPHON_IO_ERROR: i32 = -32005;
pub const SOPHON_CONFIG_ERROR: i32 = -32006;

/// Build a JSON-RPC error response envelope.
///
/// `id` may be `Null` when the server received a request without an `id`
/// field (a notification) — the JSON-RPC spec still requires the `id`
/// key to be present in error responses so clients can reconcile.
pub fn error_response(id: Value, code: i32, message: impl Into<String>) -> Value {
    json!({
        "jsonrpc": "2.0",
        "id": id,
        "error": {
            "code": code,
            "message": message.into(),
        }
    })
}

/// Error response with an extra `data` field (arbitrary JSON payload
/// attached by the server to help the client diagnose the failure).
pub fn error_response_with_data(
    id: Value,
    code: i32,
    message: impl Into<String>,
    data: Value,
) -> Value {
    json!({
        "jsonrpc": "2.0",
        "id": id,
        "error": {
            "code": code,
            "message": message.into(),
            "data": data,
        }
    })
}

/// Classify an `anyhow::Error` chain and map it to the closest Sophon
/// server error code. Falls back to `INTERNAL_ERROR` (-32603) when no
/// specific category matches.
///
/// We walk the error chain with `downcast_ref` for known types we care
/// about, otherwise inspect the display string. The chain is kept short
/// and the display strings are the existing `anyhow::anyhow!` messages
/// — this is classification, not parsing.
pub fn classify_anyhow(err: &anyhow::Error) -> i32 {
    for cause in err.chain() {
        if cause.downcast_ref::<std::io::Error>().is_some() {
            return SOPHON_IO_ERROR;
        }
        if cause.downcast_ref::<serde_json::Error>().is_some() {
            return SOPHON_TOOL_ARGUMENTS_INVALID;
        }
    }
    let msg = err.to_string().to_ascii_lowercase();
    if msg.contains("unknown tool") || msg.contains("tool not found") {
        SOPHON_TOOL_NOT_FOUND
    } else if msg.contains("invalid")
        || msg.contains("missing")
        || msg.contains("parse")
        || msg.contains("deserialize")
    {
        SOPHON_TOOL_ARGUMENTS_INVALID
    } else if msg.contains("retriever") && msg.contains("not configured") {
        SOPHON_RETRIEVER_UNAVAILABLE
    } else if msg.contains("config") {
        SOPHON_CONFIG_ERROR
    } else {
        SOPHON_TOOL_EXECUTION_FAILED
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn error_response_has_spec_shape() {
        let r = error_response(json!(42), METHOD_NOT_FOUND, "method not found: foo");
        assert_eq!(r["jsonrpc"], "2.0");
        assert_eq!(r["id"], 42);
        assert_eq!(r["error"]["code"], METHOD_NOT_FOUND);
        assert_eq!(r["error"]["message"], "method not found: foo");
        assert!(r["error"].get("data").is_none());
    }

    #[test]
    fn error_response_with_data_preserves_payload() {
        let r = error_response_with_data(
            Value::Null,
            INVALID_PARAMS,
            "missing field",
            json!({"field": "name"}),
        );
        assert_eq!(r["error"]["data"]["field"], "name");
    }

    #[test]
    fn classify_io_error() {
        let err: anyhow::Error = std::io::Error::new(std::io::ErrorKind::NotFound, "boom").into();
        assert_eq!(classify_anyhow(&err), SOPHON_IO_ERROR);
    }

    #[test]
    fn classify_unknown_tool() {
        let err = anyhow::anyhow!("unknown tool: frobnicate");
        assert_eq!(classify_anyhow(&err), SOPHON_TOOL_NOT_FOUND);
    }

    #[test]
    fn classify_missing_argument() {
        let err = anyhow::anyhow!("missing required field `query`");
        assert_eq!(classify_anyhow(&err), SOPHON_TOOL_ARGUMENTS_INVALID);
    }

    #[test]
    fn classify_generic_failure_falls_back_to_execution() {
        let err = anyhow::anyhow!("the LLM shelled out and died");
        assert_eq!(classify_anyhow(&err), SOPHON_TOOL_EXECUTION_FAILED);
    }
}

